function getImgUrl(g, cb) {
  if (!g.pid) { cb(null); return; }
  // 星4武将の場合は埋め込み画像を使用
  if (g.star===4 && STAR4_IMGS[g.id]) { cb(STAR4_IMGS[g.id]); return; }
  if (imgCache[g.pid] !== undefined) { cb(imgCache[g.pid]); return; }
  imgCache[g.pid] = null; // pending
  fetch('https://kamigame.jp/sangokushiten/page/' + g.pid + '.html')
    .then(function(r){ return r.text(); })
    .then(function(html){
      var m = html.match(/og:image[^>]+content="([^"]+)"/);
      if (!m) m = html.match(/content="([^"]+)"[^>]+og:image/);
      if (!m) {
        m = html.match(/!\[ブラウザ三国志天[^\]]+\]\((https:\/\/lh3\.googleusercontent\.com\/[^)]+)\)/);
      }
      var url = m ? m[1] : null;
      imgCache[g.pid] = url;
      cb(url);
      if (url) {
        document.querySelectorAll('[data-pid="'+g.pid+'"]').forEach(function(el){
          el.outerHTML = mkAv(el.dataset.name, el.dataset.faction, el.dataset.sz, url);
        });
      }
    })
    .catch(function(){ imgCache[g.pid] = null; cb(null); });
}

// バックグラウンドで未取得武将の画像URLを全プリフェッチ
function prefetchAllImages() {
  var delay = 0;
  GENERALS.forEach(function(g){
    if (!g.pid) return;
    if (imgCache[g.pid] !== undefined) return;
    setTimeout(function(){ getImgUrl(g, function(){}); }, delay);
    delay += 150;
  });
}

