/* ================================================================
   COOKIE STORAGE
================================================================ */
var COOKIE_KEY = 'buratenn_v1';
var COOKIE_DAYS = 60;

function getCookie(name){
  var prefix = name+'=';
  var parts = document.cookie.split(';');
  for(var i=0;i<parts.length;i++){
    var c = parts[i].trim();
    if(c.indexOf(prefix)===0) return decodeURIComponent(c.substring(prefix.length));
  }
  return null;
}

var LS_KEY = COOKIE_KEY + '_ls';

function saveState(){
  try{
    var data = { ownedG:ownedG, ownedS:ownedS, squads:squads, sqCnt:sqCnt, squadStatView:squadStatView };
    var json = JSON.stringify(data);
    localStorage.setItem(LS_KEY, json);
  }catch(e){ console.warn('save failed',e); }
}

function loadState(){
  try{
    // まずlocalStorageから読む
    var raw = null;
    try{ raw = localStorage.getItem(LS_KEY); }catch(e){}
    // なければクッキーから読む（移行用）
    if(!raw) raw = getCookie(COOKIE_KEY);
    if(!raw) return false;
    var data = JSON.parse(raw);
    if(data.ownedG){
      ownedG = data.ownedG;
      // 旧データ互換：true → {aw:0,en:0}
      for(var k in ownedG){ if(ownedG[k]===true) ownedG[k]={aw:0,en:0}; }
    }
    if(data.ownedS) ownedS = data.ownedS;
    if(data.squads) squads = data.squads;
    if(data.sqCnt !== undefined) sqCnt = data.sqCnt;
    if(data.squadStatView) squadStatView = data.squadStatView;
    return true;
  }catch(e){ console.warn('load failed',e); return false; }
}

/* 部隊番号を 1 から詰め直す */
function renumberSquads(){
  for(var i=0;i<squads.length;i++){
    var q = squads[i];
    q.id = i+1;
    if(/^第\d+部隊$/.test(q.name)) q.name = '第'+(i+1)+'部隊';
  }
  sqCnt = squads.length;
}

/* コスト計算・上限チェック */
var MAX_COST = 20;
var STATS       = ['武','防','計','速'];
var EN_STATS    = ['武','防','計','速','能'];
var EQUIP_KINDS = ['武器','防具','乗物','装飾品'];
var EQUIP_ICONS = {'武器':'⚔','防具':'🛡','乗物':'🐎','装飾品':'💍'};
// ステータスオブジェクト {武,防,計,速} の合計を返すヘルパー
function sumStats(obj){ return (obj['武']||0)+(obj['防']||0)+(obj['計']||0)+(obj['速']||0); }
function calcSquadCost(q){
  var tc=0;
  for(var si=0;si<q.slots.length;si++){
    var gg=q.slots[si].g?findG(q.slots[si].g):null;
    if(gg) tc+=gg.c;
  }
  return tc;
}
function avChar(name){ return name.replace(/[\[\]（）]/g,'')[0]; }
function eh(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

// ── 所持情報ヘルパー（後方互換：旧データは true のみ）──
function isOwnedG(id){ return !!ownedG[id]; }
function getAw(id){ var v=ownedG[id]; if(!v) return 0; return typeof v==='object'?v.aw||0:0; }
function getEn(id){ var v=ownedG[id]; if(!v) return 0; if(typeof v!=='object') return 0; if(Array.isArray(v.en)) return v.en.length; return typeof v.en==='number'?v.en:0; }
function getEnArr(id){ var v=ownedG[id]; if(!v||typeof v!=='object') return []; if(Array.isArray(v.en)) return v.en; return []; }
function getLv(id){ var v=ownedG[id]; if(!v) return 1; return typeof v==='object'?v.lv||1:1; }
function getBonus(id){ var v=ownedG[id]; if(!v||typeof v!=='object') return {武:0,防:0,計:0,速:0}; return v.bonus||{武:0,防:0,計:0,速:0}; }
function getEquip(id){ var v=ownedG[id]; if(!v||typeof v!=='object') return {}; return v.equip||{}; }
function getEquipStatTotal(id, statKey){
  var equip = getEquip(id);
  var total = 0;
  EQUIP_KINDS.forEach(function(k){
    var kData = (equip[k] && typeof equip[k]==='object') ? equip[k] : {};
    total += kData[statKey]||0;
  });
  return Math.round(total*100)/100;
}
function getAwBonus(id){ var v=ownedG[id]; if(!v||typeof v!=='object') return {武:0,防:0,計:0,速:0}; var b=v.awBonus; if(!b||Array.isArray(b)) return {武:0,防:0,計:0,速:0}; return b; }
function getEnNouBonus(id){ var v=ownedG[id]; if(!v||typeof v!=='object') return {武:0,防:0,計:0,速:0}; return v.enNouBonus||{武:0,防:0,計:0,速:0}; }
function getDedSkBonus(id){ var v=ownedG[id]; if(!v||typeof v!=='object') return {武:0,防:0,計:0,速:0}; return v.dedSkBonus||{武:0,防:0,計:0,速:0}; }
function setOwnedG(id, owned, aw, en){
  if(!owned){ delete ownedG[id]; return; }
  ownedG[id] = {aw: aw||0, en: en||0};
}
// 覚醒・強化バッジHTML（所持一覧カード用）
function awEnHtml(id){
  var aw=getAw(id), en=getEn(id);
  if(!aw && !en) return '';
  var s='<div class="aw-wrap">';
  if(aw) s+='<span class="aw-badge aw">覚'+aw+'</span>';
  if(en) s+='<span class="aw-badge en">強'+en+'</span>';
  s+='</div>';
  return s;
}
// 部隊編成スロット用のバッジHTML
function awEnSlotHtml(id){
  var aw=getAw(id), en=getEn(id);
  if(!aw && !en) return '';
  var s='<div class="pg-upgrades">';
  if(aw) s+='<span class="aw-badge aw">覚醒+'+aw+'</span>';
  if(en) s+='<span class="aw-badge en">追強+'+en+'</span>';
  s+='</div>';
  return s;
}


// ── 通常スキル定義 ──
var NORMAL_SKILLS = [
  {id:'none',  n:'なし',  b:{武:0,防:0,計:0,速:0}},
  {id:'武',    n:'武',    b:{武:5,防:0,計:0,速:0}},
  {id:'防',    n:'防',    b:{武:0,防:5,計:0,速:0}},
  {id:'速',    n:'速',    b:{武:0,防:0,計:0,速:5}},
  {id:'計',    n:'計',    b:{武:0,防:0,計:5,速:0}},
  {id:'高武',  n:'高武',  b:{武:10,防:0,計:0,速:0}},
  {id:'高防',  n:'高防',  b:{武:0,防:10,計:0,速:0}},
  {id:'高速',  n:'高速',  b:{武:0,防:0,計:0,速:10}},
  {id:'高計',  n:'高計',  b:{武:0,防:0,計:10,速:0}},
  {id:'傑武計',n:'傑武計',b:{武:10,防:0,計:10,速:0}},
  {id:'傑武防',n:'傑武防',b:{武:10,防:10,計:0,速:0}},
  {id:'傑防速',n:'傑防速',b:{武:0,防:10,計:0,速:10}},
  {id:'傑計速',n:'傑計速',b:{武:0,防:0,計:10,速:10}},
];
function findNSk(id){ for(var i=0;i<NORMAL_SKILLS.length;i++) if(NORMAL_SKILLS[i].id===id) return NORMAL_SKILLS[i]; return null; }

function getSk3tBonus(gid, statKey){
  var v = ownedG[gid];
  if(!v || typeof v !== 'object') return 0;
  var b = v.sk3tBonus || {};
  return b[statKey]||0;
}

function setSk3tBonusVal(id, stat, val){
  if(!isOwnedG(id)) return;
  var cur = ownedG[id];
  if(typeof cur !== 'object') cur = {aw:0,en:0};
  if(!cur.sk3tBonus) cur.sk3tBonus = {武:0,防:0,計:0,速:0};
  cur.sk3tBonus[stat] = parseInt(val,10)||0;
  ownedG[id] = cur;
  saveState();
  var el = document.getElementById('sk3t-'+id+'-'+stat);
  if(el) el.value = cur.sk3tBonus[stat];
}

function getSk1tBonus(gid, statKey){
  var v = ownedG[gid];
  if(!v || typeof v !== 'object') return 0;
  var b = v.sk1tBonus || {};
  return b[statKey]||0;
}

function setSk1tBonusVal(id, stat, val){
  if(!isOwnedG(id)) return;
  var cur = ownedG[id];
  if(typeof cur !== 'object') cur = {aw:0,en:0};
  if(!cur.sk1tBonus) cur.sk1tBonus = {武:0,防:0,計:0,速:0};
  cur.sk1tBonus[stat] = parseInt(val,10)||0;
  ownedG[id] = cur;
  saveState();
  var el = document.getElementById('sk1t-'+id+'-'+stat);
  if(el) el.value = cur.sk1tBonus[stat];
}
function getStatVal(id, statKey){
  var g = findG(id); if(!g||!g.stats) return 0;
  var base = g.stats[statKey]||0;
  var lv = getLv(id);
  // LV補正
  var lvVal = Math.floor(base * (1 + 0.025 * (lv - 1)) * 100) / 100;
  // LVボーナス（自由割り振り）
  var bonus = getBonus(id);
  var bonusVal = bonus[statKey]||0;
  // 覚醒ボーナス（自由割り振り）
  var awBonusObj = getAwBonus(id);
  var awBonusVal = awBonusObj[statKey]||0;
  // 追加強化：選択されたstatに+10固定
  var enArr = getEnArr(id);
  var enVal = (statKey !== '能' && enArr.indexOf(statKey) > -1) ? 10 : 0;
  // 追加強化「能」ボーナス（自由割り振り）
  var enNouBonus = getEnNouBonus(id);
  var enNouVal = enNouBonus[statKey]||0;
  // 装備補正
  var equip = getEquip(id);
  var equipVal = getEquipStatTotal(id, statKey);
    return Math.floor((lvVal + bonusVal + awBonusVal + enVal + enNouVal + equipVal) * 100) / 100;
}
function getStatsDisplay(id){
  var g = findG(id); if(!g||!g.stats) return null;
  return {武:getStatVal(id,'武'),防:getStatVal(id,'防'),計:getStatVal(id,'計'),速:getStatVal(id,'速')};
}

/* ================================================================
   SKILL BUFF ENGINE  v3
   速度順・逐次計算・条件付きバフ対応
================================================================ */

// stat文字列("武力・防御"等)を分解してtargetに加算
function parseStatStr(statsStr, val, target){
  var order = ['武力','防御','計略','速度','武','防','計','速'];
  var MAP = {'武力':'武','防御':'防','計略':'計','速度':'速','武':'武','防':'防','計':'計','速':'速'};
  var rem = statsStr;
  for(var i=0;i<order.length;i++){
    var k=order[i];
    if(rem.indexOf(k)!==-1){
      rem=rem.split(k).join('');
      var m=MAP[k]; if(m) target[m]=(target[m]||0)+val;
    }
  }
}

/*
  parseSkillEntries(d, tp)
  スキルテキスト1枚分を解析し、バフエントリの配列を返す。
  各エントリ:
    {
      target : 'self' | 'team' | 'main' | 'sub' | 'cond',
      cond   : null | '武力最高' | '防御最高' | '計略最高' | '速度最高' | '主将',
      timer  : '3t' | 'perm',   // [XT]付きなら'3t'、なければ'perm'
      stats  : {武,防,計,速}
    }
*/
function parseSkillEntries(d, tp){
  if(!d) return [];
  var entries = [];

  // デメリット記述を「自分に」に変換してマイナスバフとして解析できるようにする
  var text = d.replace(/デメリット[:：](自分に?)?/g, '自分に');
  text = text.replace(/麻痺中の[^\+、。]*(?=[、。]|$)/g,'');
  // 敵記述: 「敵〜」セグメントを除去
  text = text.replace(/敵[^\+、。]*(?=[、。]|$)/g,'');

  var segs = text.split(/[、。]/);

  // セグメントをtarget引き継ぎしながら処理
  var lastTarget = 'self';
  var lastCond   = null;

  segs.forEach(function(seg){
    if(!seg) return;

    // --- 対象判定（明示的な対象指定があるセグメントのみ更新、なければ前のtargetを引き継ぐ）---
    var target = null;
    var cond   = null;
    var hasTargetKeyword = false;

    // 主将時[:：]を最初にチェック（「主将時:味方副将に～」等で副将より先に判定）
    if(/主将時[:：]/.test(seg)){
      hasTargetKeyword = true;
      // 「主将時:全体防御+125[3T]」→team、「主将時:副将に武力+95」→sub
      if(/全体/.test(seg))       target = 'team';
      else if(/副将/.test(seg))  target = 'sub';
      else                        target = 'main_self'; // 主将自身
      cond = '__onlyMain__'; // 主将時のみ発動フラグ
    } else if(!/敵/.test(seg) && /味方全体|全体に|全体を|全体[武防計速]/.test(seg)){
      target = 'team'; hasTargetKeyword = true;
    } else if(/味方主将/.test(seg)){
      target = 'main'; hasTargetKeyword = true;
    } else if(/味方副将/.test(seg)){
      target = 'sub'; hasTargetKeyword = true;
    } else if(/武力最高の味方/.test(seg)){
      target = 'cond'; cond = '武力最高'; hasTargetKeyword = true;
    } else if(/防御最高の味方/.test(seg)){
      target = 'cond'; cond = '防御最高'; hasTargetKeyword = true;
    } else if(/計略最高の味方/.test(seg)){
      target = 'cond'; cond = '計略最高'; hasTargetKeyword = true;
    } else if(/速度最高の味方/.test(seg)){
      target = 'cond'; cond = '速度最高'; hasTargetKeyword = true;
    } else if(/武力最低の味方/.test(seg)){
      target = 'cond'; cond = '武力最低'; hasTargetKeyword = true;
    } else if(/防御最低の味方/.test(seg)){
      target = 'cond'; cond = '防御最低'; hasTargetKeyword = true;
    } else if(/計略最低の味方/.test(seg)){
      target = 'cond'; cond = '計略最低'; hasTargetKeyword = true;
    } else if(/速度最低の味方/.test(seg)){
      target = 'cond'; cond = '速度最低'; hasTargetKeyword = true;
    } else if(/自分に|自身/.test(seg)){
      // 明示的に「自分に」→selfにリセット
      target = 'self'; hasTargetKeyword = true;
    }

    // 対象キーワードがなければ直前のtarget/condを引き継ぐ
    if(!hasTargetKeyword){
      target = lastTarget;
      cond   = lastCond;
    } else {
      lastTarget = target;
      // __onlyMain__フラグは引き継がない（次のセグメントには伝搬させない）
      lastCond   = (cond === '__onlyMain__') ? null : cond;
    }

    // --- [XT]付きバフ（プラス） ---
    var re3t = /([武防計速力略御度・]+)\+([0-9]+)\[[0-9]+T\]/g;
    var m;
    while((m=re3t.exec(seg))!==null){
      var stats={武:0,防:0,計:0,速:0};
      parseStatStr(m[1], parseInt(m[2]), stats);
      entries.push({target:target, cond:cond, timer:'3t', stats:stats});
    }

    // --- [XT]付きデバフ（マイナス） ---
    var re3tM = /([武防計速力略御度・]+)-([0-9]+)\[[0-9]+T\]/g;
    while((m=re3tM.exec(seg))!==null){
      var statsM={武:0,防:0,計:0,速:0};
      parseStatStr(m[1], -parseInt(m[2]), statsM);
      entries.push({target:target, cond:cond, timer:'3t', stats:statsM});
    }

    // --- 永続バフ（[XT]なし、プラス） ---
    var segNT = seg.replace(/[武防計速力略御度・]+[+\-][0-9]+\[[0-9]+T\]/g,'');
    var reP = /([武防計速力略御度・]+)\+([0-9]+)/g;
    while((m=reP.exec(segNT))!==null){
      var stats2={武:0,防:0,計:0,速:0};
      parseStatStr(m[1], parseInt(m[2]), stats2);
      entries.push({target:target, cond:cond, timer:'perm', stats:stats2});
    }

    // --- 永続デバフ（[XT]なし、マイナス） ---
    var rePM = /([武防計速力略御度・]+)-([0-9]+)/g;
    while((m=rePM.exec(segNT))!==null){
      var stats3={武:0,防:0,計:0,速:0};
      parseStatStr(m[1], -parseInt(m[2]), stats3);
      entries.push({target:target, cond:cond, timer:'perm', stats:stats3});
    }
  });

  return entries;
}

/*
  calcSquadSkillBuffs(squad)
  速度順→固有→sk1→sk2 の順に逐次計算。
  条件付きバフ（武力最高の味方など）はその時点の累積値で判定。
  戻り値: 各スロット index に対応する {t3:{武,防,計,速}, all:{武,防,計,速}}
*/
function calcSquadSkillBuffs(squad){
  var zero=function(){return{武:0,防:0,計:0,速:0};};
  var slots = squad.slots;

  // スロットごとの武将情報
  var members = slots.map(function(slot, si){
    var g = slot.g ? findG(slot.g) : null;
    return {
      si   : si,
      g    : g,
      slot : slot,
      isMain : si===0,
      // 現時点のバフ累積（速度順処理中に更新）
      cur3t  : zero(),
      curAll : zero()
    };
  });

  // 速度順にソート（速い順）— 速度はgetStatVal込み
  var active = members.filter(function(m){ return !!m.g; });
  active.sort(function(a,b){
    return getStatVal(b.g.id,'速') - getStatVal(a.g.id,'速');
  });

  // スキルリスト生成（固有→sk1→sk2）
  function getSkills(member){
    var g=member.g, slot=member.slot;
    var list=[];
    var fxsk=getFxSkill(g); if(fxsk) list.push(fxsk);
    var sk0=slot.sk[0]?findS(slot.sk[0]):null; if(sk0) list.push(sk0);
    var sk1=slot.sk[1]?findS(slot.sk[1]):null; if(sk1) list.push(sk1);
    return list;
  }

  // 現時点の累積値を取得（ベース+バフ）
  function getCurVal(member, stat){
    return getStatVal(member.g.id, stat)
         + (member.cur3t[stat]||0)
         + (member.curAll[stat]||0);
  }

  // condバフの対象者を現時点の累積値で判定
  function resolveCondTarget(cond, members){
    var alive = members.filter(function(m){ return !!m.g; });
    if(!alive.length) return null;
    var stat = cond.replace('最高','').replace('最低','');
    var statKey = {'武力':'武','防御':'防','計略':'計','速度':'速',
                   '武':'武','防':'防','計':'計','速':'速'}[stat];
    if(!statKey) return null;
    var isMax = cond.indexOf('最高')!==-1;
    var best = alive[0];
    var bestVal = getCurVal(best, statKey);
    for(var i=1;i<alive.length;i++){
      var v=getCurVal(alive[i], statKey);
      if(isMax ? v>bestVal : v<bestVal){ best=alive[i]; bestVal=v; }
    }
    return best;
  }

  // バフを対象メンバーに適用
  function applyBuff(targetMember, entry){
    STATS.forEach(function(s){
      if(entry.timer==='3t')  targetMember.cur3t[s] = (targetMember.cur3t[s]||0) + (entry.stats[s]||0);
      else                    targetMember.curAll[s]= (targetMember.curAll[s]||0)+ (entry.stats[s]||0);
    });
  }

  // 速度順で各武将のスキルを処理
  var usedSkillIds = {};   // 部隊内で既に発動済みのスキルID（重複加算防止）
  var usedSkillNames = {}; // 同名スキルも重複扱い（固有スキルとスキルカードの同名対応）
  active.forEach(function(actor){
    var skills = getSkills(actor);
    skills.forEach(function(sk){
      // passiveは自分が持つスキルなのでそのまま処理（速度順で処理済み）
      if(sk.tp !== 'start') return; // 始動スキルのみ計算
      // 同一スキル（ID一致 or 名前一致）が部隊内で既に発動済みならスキップ
      if(usedSkillIds[sk.id] || usedSkillNames[sk.n]) return;
      usedSkillIds[sk.id] = true;
      usedSkillNames[sk.n] = true;
      var entries = parseSkillEntries(sk.d, sk.tp);
      entries.forEach(function(e){
        switch(e.target){
          case 'self':
            applyBuff(actor, e);
            break;
          case 'main_self':
            // 主将時に発動する能力 → 主将（si===0）の時のみ適用
            if(actor.isMain) applyBuff(actor, e);
            break;
          case 'team':
            // 主将時フラグがある場合は主将のみが発動できる
            if(e.cond === '__onlyMain__' && !actor.isMain) break;
            members.forEach(function(m){ if(m.g) applyBuff(m, e); });
            break;
          case 'main':
            if(members[0] && members[0].g) applyBuff(members[0], e);
            break;
          case 'sub':
            // 主将時フラグがある場合は主将のみが発動できる
            if(e.cond === '__onlyMain__' && !actor.isMain) break;
            for(var i=1;i<members.length;i++){
              if(members[i].g) applyBuff(members[i], e);
            }
            break;
          case 'cond':
            var tgt = resolveCondTarget(e.cond, members);
            if(tgt) applyBuff(tgt, e);
            break;
        }
      });
    });
  });

  // 結果を元のスロット順で返す
  return members.map(function(m){
    if(!m.g) return null;
    return { t3: m.cur3t, all: m.curAll };
  });
}


var squadStatView = {};

function getStatViewMode(qid){
  return squadStatView[qid] || {t1:false, t3:false, all:false};
}

function toggleStatView(qid, mode){
  var sv = getStatViewMode(qid);
  var isOn = sv[mode];
  // 排他選択：同じボタンを押したらOFF、別ボタンを押したら切り替え
  var next = {t1:false, t3:false, all:false};
  if(!isOn) next[mode] = true;
  squadStatView[qid] = next;
  saveState();
  renderSquads();
}


function factionAvClass(f){
  return {魏:'fWei',呉:'fWu',蜀:'fShu',他:'fOth'}[f]||'fOth';
}
function mkAv(name, faction, size, imgUrl){
  var cls = 'av av-'+size+' '+factionAvClass(faction);
  if(imgUrl){
    return '<div class="'+cls+'" style="padding:0;overflow:hidden;">'
          +'<img src="'+imgUrl+'" alt="'+eh(name)+'" style="width:100%;height:100%;object-fit:cover;object-position:top center;">'
          +'</div>';
  }
  return '<div class="'+cls+'">'+avChar(name)+'</div>';
}
/* 画像付きアバターを非同期で差し替え */
function mkAvAsync(name, faction, size, g, elemId){
  if(!g || !g.pid) return mkAv(name, faction, size, null);
  // 星4武将: 埋め込み画像を即座に使用
  if(g.star===4 && STAR4_IMGS[g.id]) return mkAv(name, faction, size, STAR4_IMGS[g.id]);
  var cached = imgCache[g.pid];
  // キャッシュ済み（URL確定）: 即座に画像付きで返す
  if(cached) return mkAv(name, faction, size, cached);
  // プレースホルダー: data属性を持たせて getImgUrl 内の querySelectorAll から mkAv で更新できるようにする
  var placeholder = '<div id="'+elemId+'"'
    +' data-pid="'+g.pid+'" data-name="'+eh(name)+'" data-faction="'+faction+'" data-sz="'+size+'"'
    +' class="av av-'+size+' '+factionAvClass(faction)+'" style="position:relative;overflow:hidden;">'
    +'<span class="av-txt">'+avChar(name)+'</span></div>';
  // pending中（null）: プリフェッチ完了後に getImgUrl の querySelectorAll が更新する
  if(cached === null) return placeholder;
  // 未取得: 非同期取得してコールバックで差し替え
  getImgUrl(g, function(url){
    if(!url) return;
    var el = document.getElementById(elemId);
    if(!el) return;
    el.outerHTML = mkAv(name, faction, size, url);
  });
  return placeholder;
}
