function showChangelog(){
  var panel = document.getElementById('changelog-panel');
  if(!panel.classList.contains('hide')){
    hideChangelog();
    return;
  }
  var typeLabel = {new:'NEW', fix:'FIX', change:'変更'};
  var html = '';
  for(var i=0;i<CHANGELOG.length;i++){
    var entry = CHANGELOG[i];
    html += '<div class="cl-entry">';
    html += '<div class="cl-ver"><span class="cl-ver-num">'+entry.ver+'</span><span class="cl-ver-date">'+entry.date+'</span></div>';
    for(var j=0;j<entry.items.length;j++){
      var item = entry.items[j];
      html += '<div class="cl-item"><span class="cl-badge '+item.type+'">'+typeLabel[item.type]+'</span><span>'+eh(item.text)+'</span></div>';
    }
    html += '</div>';
    if(i < CHANGELOG.length-1) html += '<hr style="border:none;border-top:1px solid var(--bd);margin:0 0 12px;">';
  }
  document.getElementById('changelog-body').innerHTML = html;
  panel.classList.remove('hide');
}
