function getUsedG(){
  var s={};
  for(var qi=0;qi<squads.length;qi++)
    for(var si=0;si<squads[qi].slots.length;si++){
      var g=squads[qi].slots[si].g; if(g) s[g]=true;
    }
  return s;
}
function getUsedS(){
  var s={};
  for(var qi=0;qi<squads.length;qi++)
    for(var si=0;si<squads[qi].slots.length;si++){
      var sk=squads[qi].slots[si].sk;
      for(var ki=0;ki<sk.length;ki++) if(sk[ki]) s[sk[ki]]=true;
    }
  return s;
}
function findG(id){ for(var i=0;i<GENERALS.length;i++) if(GENERALS[i].id===id) return GENERALS[i]; return null; }
function findS(id){ for(var i=0;i<SKILLS.length;i++) if(SKILLS[i].id===id) return SKILLS[i]; return null; }
function findSq(id){ for(var i=0;i<squads.length;i++) if(squads[i].id===id) return squads[i]; return null; }
// 武将オブジェクトから固有スキルを取得
function getFxSkill(g){
  if(!g) return null;
  // ALL_SKILLSのnフィールドとg.fxが一致するものを探す
  for(var i=0;i<ALL_SKILLS.length;i++){
    if(ALL_SKILLS[i].n===g.fx) return ALL_SKILLS[i];
  }
  return null;
}

